import { z } from 'zod';

/**
 * Human-review authoring manifest for the 2026 catalog expansion.
 *
 * These records intentionally keep venue coordinates and event dates in a
 * reviewable form. The generator produces complete preview records, while the
 * publish validator requires Google identity checks and editorial approval.
 */
export const DestinationAuthorSchema = z.object({
  wave: z.enum(['lgbtq_priority', 'global_popular']),
  slug: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  name: z.string().min(2),
  country: z.string().min(2),
  countryCode: z.string().regex(/^[A-Z]{2}$/),
  continentCode: z.enum(['NA', 'SA', 'EU', 'AS', 'AF', 'OC']),
  destinationType: z.enum(['city', 'island', 'resort_area']).optional(),
  lat: z.number().min(-90).max(90),
  lng: z.number().min(-180).max(180),
  timezone: z.string().min(3),
  currency: z.string().regex(/^[A-Z]{3}$/),
  airports: z.array(z.string().regex(/^[A-Z]{3}$/)).min(1),
  climate: z.string().min(3),
  bestMonths: z.array(z.number().int().min(1).max(12)).min(1),
  costs: z.tuple([z.number().positive(), z.number().positive(), z.number().positive()]),
  legalStatus: z.enum(['marriage_equality', 'civil_union', 'limited_protections', 'no_recognition', 'criminalized', 'heavily_criminalized']),
  legalScore: z.number().min(0).max(100),
  publicScore: z.number().min(0).max(100),
  advisory: z.enum(['standard', 'caution', 'elevated', 'severe']),
  nightlife: z.number().min(0).max(100),
  interests: z.array(z.string().min(2)).min(4),
  summary: z.string().min(80),
  context: z.string().min(80),
  neighborhoods: z.array(z.string().min(2)).min(2),
  places: z.array(z.tuple([z.string().min(2), z.enum(['community', 'shop', 'bar', 'museum', 'landmark', 'park', 'beach', 'spa', 'restaurant'])])).min(6),
  events: z.array(z.tuple([z.string().min(2), z.number().int().min(1).max(12), z.enum(['pride', 'festival'])])).min(2),
  tourismUrl: z.string().url().startsWith('https://'),
  communityUrl: z.string().url().startsWith('https://'),
  publicationStatus: z.enum(['draft', 'published']).optional(),
  editorialReview: z.object({
    status: z.enum(['pending', 'approved', 'rejected']),
    legalContextReviewed: z.boolean(),
    placesValidated: z.boolean(),
    reviewedAt: z.string().datetime().nullable(),
  }).optional(),
  catalogFreshness: z.object({
    legalContextReviewedAt: z.string().datetime().nullable(),
    venuesReviewedAt: z.string().datetime().nullable(),
    eventsReviewedAt: z.string().datetime().nullable(),
    pricingReviewedAt: z.string().datetime().nullable(),
    climateReviewedAt: z.string().datetime().nullable(),
  }).optional(),
}).strict();

